def ch(c):
 r,g,b=c
 if r<25 and g<25 and b<25:return '#'
 if b>r+15:return 'B'
 if r-b>25:
  return 'O' if g>40 else ('R' if r>70 else 'r')
 if abs(r-g)<8 and abs(g-b)<8:
